import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useData } from '../context/DataContext';

const headlines = [
  "Unlocking Biblical Secrets",
  "Unsealing Biblical Secrets",
  "Unlocking Biblical Truths",
  "Exposing Theological Tricks",
  "Liberating the Masses"
];

const Home: React.FC = () => {
  const { merch, posts } = useData();
  const [displayText, setDisplayText] = useState("");
  const [headlineIndex, setHeadlineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [isDeleting, setIsDeleting] = useState(false);

  const latestPosts = posts.slice(0, 4);

  useEffect(() => {
    const currentHeadline = headlines[headlineIndex];
    const typeSpeed = isDeleting ? 50 : 100;

    const timeout = setTimeout(() => {
      if (!isDeleting && charIndex < currentHeadline.length) {
        setDisplayText(prev => prev + currentHeadline[charIndex]);
        setCharIndex(prev => prev + 1);
      } else if (isDeleting && charIndex > 0) {
        setDisplayText(prev => prev.slice(0, -1));
        setCharIndex(prev => prev - 1);
      } else if (!isDeleting && charIndex === currentHeadline.length) {
        setTimeout(() => setIsDeleting(true), 2000);
      } else if (isDeleting && charIndex === 0) {
        setIsDeleting(false);
        setHeadlineIndex(prev => (prev + 1) % headlines.length);
      }
    }, typeSpeed);

    return () => clearTimeout(timeout);
  }, [charIndex, isDeleting, headlineIndex]);

  return (
    <div className="flex flex-col">
      {/* Hero Section */}
      <section className="relative min-h-[85vh] flex items-center justify-center overflow-hidden">
        <div className="absolute inset-0 z-0">
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-brand-start/20 rounded-full blur-[120px]"></div>
          <div className="absolute bottom-0 right-0 w-[400px] h-[400px] bg-brand-end/30 rounded-full blur-[100px]"></div>
        </div>

        <div className="relative z-10 max-w-7xl mx-auto px-4 text-center">
          <h1 className="font-orbitron font-black text-5xl md:text-8xl mb-8 leading-tight tracking-tighter">
            <span className="wipe-text block animate-wipe-in">
              {displayText}
              <span className="typing-cursor"></span>
            </span>
          </h1>
          <p className="text-lg md:text-2xl text-slate-500 dark:text-slate-400 mb-12 max-w-2xl mx-auto font-light leading-relaxed">
            The Bible is clear; the theology is the trick. Reject religious assumptions, and the truth will rain like a torrent.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link to="/blog" className="px-8 py-4 gradient-bg text-white font-orbitron font-bold rounded-full hover:scale-105 transition-transform shadow-xl shadow-brand-start/20">
              EXPLORE TRUTH
            </Link>
            <Link to="/books" className="px-8 py-4 border-2 border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white font-orbitron font-bold rounded-full hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
              VIEW BOOKS
            </Link>
          </div>
        </div>
      </section>

      {/* Latest Blog Posts Section */}
      <section className="py-24 max-w-7xl mx-auto px-4 w-full animate-wipe-in">
        <div className="flex flex-col md:flex-row justify-between items-center md:items-end mb-12 gap-6">
          <div className="text-center md:text-left">
            <h2 className="font-orbitron font-bold text-xs tracking-[0.4em] text-brand-start mb-2 uppercase">Neural Intel Feed</h2>
            <h3 className="font-orbitron font-black text-4xl md:text-5xl uppercase tracking-tighter">Latest Revelations</h3>
          </div>
          <Link to="/blog" className="group flex items-center gap-3 text-[10px] font-orbitron font-bold text-slate-500 hover:text-brand-start transition-all uppercase tracking-widest bg-slate-100 dark:bg-slate-900/50 px-6 py-3 rounded-full border border-slate-200 dark:border-slate-800">
            Access Full Archives
            <svg className="w-4 h-4 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8l4 4m0 0l-4 4m4-4H3" />
            </svg>
          </Link>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {latestPosts.map((post) => (
            <Link 
              key={post.id} 
              to="/blog" 
              className="group bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[28px] overflow-hidden hover:-translate-y-2 transition-all duration-500 shadow-sm hover:shadow-2xl hover:shadow-brand-start/15"
            >
              <div className="aspect-[16/10] overflow-hidden relative">
                <img src={post.image} alt={post.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                <div className="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-4">
                   <span className="text-[8px] font-orbitron font-bold text-brand-start uppercase tracking-widest mb-1">DECRYPTING...</span>
                </div>
              </div>
              <div className="p-6">
                <div className="flex items-center justify-between mb-3">
                   <span className="text-[9px] font-orbitron font-bold text-brand-start/80 uppercase tracking-widest">{post.category}</span>
                   <span className="text-[8px] text-slate-500 font-bold uppercase">{new Date(post.date).toLocaleDateString()}</span>
                </div>
                <h4 className="font-orbitron font-bold text-base mb-3 leading-snug group-hover:text-brand-start transition-colors uppercase tracking-tight line-clamp-2">
                  {post.title}
                </h4>
                <p className="text-slate-500 dark:text-slate-400 text-xs line-clamp-2 leading-relaxed mb-6">
                  {post.excerpt}
                </p>

                <div className="flex items-center justify-between">
                  <span className="text-[10px] font-orbitron font-black text-brand-start uppercase tracking-[0.2em] group-hover:translate-x-1 transition-transform flex items-center gap-2">
                    READ MORE
                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                    </svg>
                  </span>
                </div>

                <div className="mt-4 h-0.5 w-0 group-hover:w-full bg-brand-start transition-all duration-500"></div>
              </div>
            </Link>
          ))}
        </div>
      </section>

      {/* Merch Strip */}
      <section className="bg-slate-50 dark:bg-slate-900/50 py-24 overflow-hidden border-y border-slate-200 dark:border-slate-800">
        <div className="max-w-7xl mx-auto px-4 mb-12 flex justify-between items-end">
          <div>
            <h2 className="font-orbitron font-bold text-xs tracking-[0.4em] text-brand-start mb-2 uppercase">Physical Artifacts</h2>
            <h3 className="font-orbitron font-black text-3xl uppercase tracking-tighter">Trick Theology Apparel</h3>
          </div>
          <Link to="/merch" className="text-xs font-bold uppercase tracking-widest text-slate-500 hover:text-brand-start transition-colors border-b border-slate-300 dark:border-slate-700 pb-1">Browse All</Link>
        </div>

        <div className="relative flex whitespace-nowrap overflow-hidden">
          <div className="flex animate-slide-left hover:[animation-play-state:paused]">
            {[...merch, ...merch].map((item, idx) => (
              <a
                key={`${item.id}-${idx}`}
                href={item.link}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-block mx-4 w-64 md:w-80 bg-white dark:bg-slate-950 rounded-2xl overflow-hidden shadow-lg card-glow transition-all border border-slate-200 dark:border-slate-800"
              >
                <div className="aspect-[4/5] relative overflow-hidden">
                  <img src={item.image} alt={item.title} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent flex flex-col justify-end p-6 opacity-0 hover:opacity-100 transition-opacity">
                    <p className="text-white font-bold text-lg leading-tight mb-1">{item.title}</p>
                    <p className="text-brand-start font-orbitron font-bold text-[10px] uppercase tracking-widest">
                      View on {item.platform}
                    </p>
                  </div>
                </div>
              </a>
            ))}
          </div>
        </div>
      </section>

      {/* Philosophy Section */}
      <section className="py-32 max-w-5xl mx-auto px-4 text-center">
        <div className="inline-block p-1 mb-8 rounded-full gradient-bg">
          <div className="px-4 py-1 bg-white dark:bg-slate-950 rounded-full">
            <span className="text-xs font-orbitron font-bold tracking-[0.3em] text-brand-start uppercase">VISION</span>
          </div>
        </div>
        <h2 className="font-orbitron font-bold text-4xl mb-6">Inspired to Unseal the ancient Secrets.</h2>
        <p className="text-xl text-slate-500 dark:text-slate-400 leading-relaxed italic font-light">
          "The secrets of the ages were sealed in ancient Israel. They are encoded in the fabric of our reality, waiting for the true Israelites with the keys to unseal them. They were sealed by our ancestors, waiting to be unsealed by modern Israelites."
        </p>
      </section>
    </div>
  );
};

export default Home;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { BRAND_LOGO_URL } from '../constants';
import { useData } from '../context/DataContext';
import { BlogPost, PodcastEpisode, Book, MerchItem } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

interface NavbarProps {
  isDarkMode: boolean;
  toggleTheme: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ isDarkMode, toggleTheme }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isNeuralLoading, setIsNeuralLoading] = useState(false);

  const [results, setResults] = useState<{
    posts: BlogPost[];
    podcasts: PodcastEpisode[];
    books: Book[];
    merch: MerchItem[];
  }>({ posts: [], podcasts: [], books: [], merch: [] });

  const [aiMatches, setAiMatches] = useState<{
    postIds: string[];
    podcastIds: string[];
    bookIds: string[];
    merchIds: string[];
  }>({ postIds: [], podcastIds: [], bookIds: [], merchIds: [] });

  const { posts, podcasts, books, merch } = useData();
  const location = useLocation();
  const navigate = useNavigate();
  const searchRef = useRef<HTMLDivElement>(null);

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Blog', path: '/blog' },
    { name: 'Podcast', path: '/podcast' },
    { name: 'Books', path: '/books' },
    { name: 'Merch', path: '/merch' },
    { name: 'About', path: '/about' },
    { name: 'Connect', path: '/connect' },
  ];

  const isActive = (path: string) => location.pathname === path;

  // Simple Keyword Search Logic
  useEffect(() => {
    if (searchQuery.length < 2) {
      setResults({ posts: [], podcasts: [], books: [], merch: [] });
      setAiMatches({ postIds: [], podcastIds: [], bookIds: [], merchIds: [] });
      return;
    }

    const q = searchQuery.toLowerCase();

    const filteredPosts = posts.filter(p => 
      p.title.toLowerCase().includes(q) || p.excerpt.toLowerCase().includes(q)
    ).slice(0, 3);

    const filteredPodcasts = podcasts.filter(p => 
      p.title.toLowerCase().includes(q) || p.description.toLowerCase().includes(q)
    ).slice(0, 3);

    const filteredBooks = books.filter(b => 
      b.title.toLowerCase().includes(q) || b.subtitle.toLowerCase().includes(q) || b.description.toLowerCase().includes(q)
    ).slice(0, 3);

    const filteredMerch = merch.filter(m => 
      m.title.toLowerCase().includes(q) || m.description.toLowerCase().includes(q)
    ).slice(0, 3);

    setResults({ posts: filteredPosts, podcasts: filteredPodcasts, books: filteredBooks, merch: filteredMerch });
  }, [searchQuery, posts, podcasts, books, merch]);

  // Deep Neural Search Logic using Gemini
  const performNeuralScan = async () => {
    if (searchQuery.length < 3) return;

    setIsNeuralLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Prepare searchable metadata for the AI
      const searchableContext = {
        posts: posts.map(p => ({ id: p.id, title: p.title, context: p.excerpt })),
        podcasts: podcasts.map(p => ({ id: p.id, title: p.title, context: p.description })),
        books: books.map(b => ({ id: b.id, title: b.title, context: b.subtitle })),
        merch: merch.map(m => ({ id: m.id, title: m.title, context: m.description }))
      };

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this theological query: "${searchQuery}". Match it against the following content archives and return only the IDs of the most relevant items in JSON format.

        Archives:
        ${JSON.stringify(searchableContext)}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              postIds: { type: Type.ARRAY, items: { type: Type.STRING } },
              podcastIds: { type: Type.ARRAY, items: { type: Type.STRING } },
              bookIds: { type: Type.ARRAY, items: { type: Type.STRING } },
              merchIds: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ["postIds", "podcastIds", "bookIds", "merchIds"]
          }
        }
      });

      const aiResults = JSON.parse(response.text);
      setAiMatches(aiResults);

      // Merge results while prioritizing AI matches
      const mergedPosts = Array.from(new Set([...posts.filter(p => aiResults.postIds.includes(p.id)), ...results.posts])).slice(0, 5);
      const mergedPodcasts = Array.from(new Set([...podcasts.filter(p => aiResults.podcastIds.includes(p.id)), ...results.podcasts])).slice(0, 5);
      const mergedBooks = Array.from(new Set([...books.filter(b => aiResults.bookIds.includes(b.id)), ...results.books])).slice(0, 5);
      const mergedMerch = Array.from(new Set([...merch.filter(m => aiResults.merchIds.includes(m.id)), ...results.merch])).slice(0, 5);

      setResults({ posts: mergedPosts, podcasts: mergedPodcasts, books: mergedBooks, merch: mergedMerch });
    } catch (error) {
      console.error("Neural Scan failed:", error);
    } finally {
      setIsNeuralLoading(false);
    }
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setIsSearchOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const closeSearch = () => {
    setIsSearchOpen(false);
    setSearchQuery('');
    setAiMatches({ postIds: [], podcastIds: [], bookIds: [], merchIds: [] });
  };

  const navigateTo = (path: string) => {
    navigate(path);
    closeSearch();
  };

  const isAiMatched = (type: keyof typeof aiMatches, id: string) => aiMatches[type].includes(id);

  return (
    <nav className="fixed top-0 w-full z-50 backdrop-blur-lg bg-white/80 dark:bg-slate-950/80 border-b border-slate-200 dark:border-slate-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center">
            <Link to="/" className="flex items-center space-x-3">
              <div className="w-10 h-10 overflow-hidden rounded-full flex items-center justify-center border border-slate-200 dark:border-slate-800 shadow-sm bg-slate-100 dark:bg-slate-900">
                <img 
                  src={BRAND_LOGO_URL} 
                  alt="Trick Theology Logo" 
                  className="w-full h-full object-cover scale-110"
                />
              </div>
              <span className="font-orbitron font-bold text-lg hidden lg:block tracking-tighter uppercase">
                <span className="text-brand-start">TRICK</span> THEOLOGY
              </span>
            </Link>
          </div>

          <div className="hidden md:flex items-center space-x-6">
            <div className="relative" ref={searchRef}>
              <div className={`flex items-center bg-slate-100 dark:bg-slate-900 rounded-full border transition-all duration-300 ${isSearchOpen ? 'w-64 border-brand-start/50' : 'w-10 border-transparent'}`}>
                <button 
                  onClick={() => setIsSearchOpen(!isSearchOpen)}
                  className="p-2 text-slate-500 hover:text-brand-start transition-colors"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </button>
                {isSearchOpen && (
                  <input
                    autoFocus
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Ask a theological question..."
                    className="bg-transparent border-none outline-none text-xs font-orbitron font-bold text-slate-800 dark:text-white w-full pr-4 placeholder:text-slate-500"
                    onKeyDown={(e) => e.key === 'Enter' && performNeuralScan()}
                  />
                )}
              </div>

              {isSearchOpen && searchQuery.length >= 2 && (
                <div className="absolute top-12 right-0 w-[420px] bg-white dark:bg-slate-900/95 backdrop-blur-2xl border border-slate-200 dark:border-slate-800 rounded-3xl shadow-2xl p-6 animate-wipe-in max-h-[80vh] overflow-y-auto custom-scrollbar">

                  {/* Neural Scan Trigger */}
                  <div className="mb-6 pb-6 border-b border-slate-100 dark:border-slate-800">
                    <button 
                      onClick={performNeuralScan}
                      disabled={isNeuralLoading}
                      className={`w-full py-3 rounded-2xl flex items-center justify-center gap-3 font-orbitron font-bold text-[10px] tracking-widest transition-all ${
                        isNeuralLoading 
                          ? 'bg-brand-start/5 text-brand-start border border-brand-start/20 cursor-wait' 
                          : 'gradient-bg text-white hover:scale-[1.02] shadow-xl shadow-brand-start/20'
                      }`}
                    >
                      {isNeuralLoading ? (
                        <>
                          <div className="flex gap-1">
                            <span className="w-1.5 h-1.5 rounded-full bg-brand-start animate-ping"></span>
                            <span className="w-1.5 h-1.5 rounded-full bg-brand-start animate-ping delay-75"></span>
                            <span className="w-1.5 h-1.5 rounded-full bg-brand-start animate-ping delay-150"></span>
                          </div>
                          NEURAL SCANNING ARCHIVES...
                        </>
                      ) : (
                        <>
                          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                          </svg>
                          ACTIVATE DEEP NEURAL SCAN
                        </>
                      )}
                    </button>
                    <p className="text-[8px] text-center mt-3 text-slate-500 font-bold uppercase tracking-widest opacity-50">AI-powered semantic matching of the archives</p>
                  </div>

                  <div className="space-y-8">
                    {/* Blog Results */}
                    {results.posts.length > 0 && (
                      <div>
                        <h4 className="text-[10px] font-orbitron font-black text-brand-start mb-4 tracking-[0.3em] uppercase opacity-50 flex items-center justify-between">
                          Blog Nodes
                        </h4>
                        <div className="space-y-3">
                          {results.posts.map(post => (
                            <button key={post.id} onClick={() => navigateTo('/blog')} className="w-full text-left group">
                              <div className="flex justify-between items-start gap-2">
                                <p className="text-sm font-bold text-slate-800 dark:text-white group-hover:text-brand-start transition-colors uppercase truncate flex-grow">{post.title}</p>
                                {isAiMatched('postIds', post.id) && (
                                  <span className="bg-brand-start/10 text-brand-start text-[8px] px-2 py-0.5 rounded font-black uppercase tracking-widest border border-brand-start/20">Neural Match</span>
                                )}
                              </div>
                              <p className="text-[10px] text-slate-500 truncate">{post.excerpt}</p>
                            </button>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Podcast Results */}
                    {results.podcasts.length > 0 && (
                      <div>
                        <h4 className="text-[10px] font-orbitron font-black text-brand-start mb-4 tracking-[0.3em] uppercase opacity-50">Audio Streams</h4>
                        <div className="space-y-3">
                          {results.podcasts.map(ep => (
                            <button key={ep.id} onClick={() => navigateTo('/podcast')} className="w-full text-left group">
                               <div className="flex justify-between items-start gap-2">
                                <p className="text-sm font-bold text-slate-800 dark:text-white group-hover:text-brand-start transition-colors uppercase truncate flex-grow">EP {ep.episodeNumber}: {ep.title}</p>
                                {isAiMatched('podcastIds', ep.id) && (
                                  <span className="bg-brand-start/10 text-brand-start text-[8px] px-2 py-0.5 rounded font-black uppercase tracking-widest border border-brand-start/20">Neural Match</span>
                                )}
                              </div>
                              <p className="text-[10px] text-slate-500 truncate">{ep.description}</p>
                            </button>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Merch Results */}
                    {results.merch.length > 0 && (
                      <div>
                        <h4 className="text-[10px] font-orbitron font-black text-brand-start mb-4 tracking-[0.3em] uppercase opacity-50">Physical Artifacts</h4>
                        <div className="space-y-3">
                          {results.merch.map(item => (
                            <button key={item.id} onClick={() => navigateTo('/merch')} className="w-full text-left group">
                              <div className="flex justify-between items-start gap-2">
                                <p className="text-sm font-bold text-slate-800 dark:text-white group-hover:text-brand-start transition-colors uppercase truncate flex-grow">{item.title}</p>
                                {isAiMatched('merchIds', item.id) && (
                                  <span className="bg-brand-start/10 text-brand-start text-[8px] px-2 py-0.5 rounded font-black uppercase tracking-widest border border-brand-start/20">Neural Match</span>
                                )}
                              </div>
                              <p className="text-[10px] text-slate-500 truncate">{item.description}</p>
                            </button>
                          ))}
                        </div>
                      </div>
                    )}

                    {Object.values(results).every(arr => arr.length === 0) && (
                      <div className="text-center py-12">
                        <div className="w-16 h-16 bg-slate-100 dark:bg-slate-900 rounded-full flex items-center justify-center mx-auto mb-4 border-2 border-dashed border-slate-200 dark:border-slate-800">
                          <span className="text-2xl opacity-20">📡</span>
                        </div>
                        <p className="text-xs font-orbitron font-bold text-slate-500 uppercase tracking-widest">No signals detected in the archive.</p>
                        <p className="text-[9px] text-slate-600 mt-2 uppercase tracking-widest font-black">Try activating the Deep Neural Scan</p>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`text-[10px] font-orbitron font-bold tracking-widest uppercase transition-colors hover:text-brand-start ${
                  isActive(link.path) ? 'text-brand-start' : 'text-slate-600 dark:text-slate-300'
                }`}
              >
                {link.name}
              </Link>
            ))}

            <div className="w-px h-6 bg-slate-200 dark:bg-slate-800 mx-2"></div>

            <button
              onClick={toggleTheme}
              className="p-2 rounded-xl bg-slate-100 dark:bg-slate-900 text-slate-600 dark:text-slate-300 hover:text-brand-start transition-colors"
            >
              {isDarkMode ? '🌞' : '🌙'}
            </button>
          </div>

          <div className="md:hidden flex items-center space-x-2">
