  { name: 'YouTube', value: 400, color: '#ff0000' },
  { name: 'Spotify', value: 300, color: '#1db954' },
  { name: 'RedCircle', value: 200, color: '#c900ff' },
];

type Tab = 'analytics' | 'blog' | 'podcasts' | 'books' | 'merch' | 'comments' | 'pages' | 'security';

const Dashboard: React.FC = () => {
  const { 
    posts, podcasts, books, merch, comments, pages, adminConfig, logout,
    addPost, updatePost, addPodcast, deleteItem, updateAdmin, updatePage, addPage, addBook, addMerch, updateCommentStatus
  } = useData();
  const { showToast } = useToast();
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState<Tab>('analytics');
  const blogFileRef = useRef<HTMLInputElement>(null);
  const podcastFileRef = useRef<HTMLInputElement>(null);
  const blogEditorRef = useRef<HTMLDivElement>(null);

  // Podcast Form State
  const [podcastForm, setPodcastForm] = useState({ 
    title: '', 
    description: '', 
    thumbnail: '', 
    episodeNumber: podcasts.length + 1, 
    sourceUrl: '', // The public link
    embedUrl: '', // The resolved iframe link
    platform: 'YouTube' as 'YouTube' | 'Spotify' | 'RedCircle' 
  });
  const [isGeneratingSEO, setIsGeneratingSEO] = useState(false);

  // Platform Embed Resolvers
  const resolveEmbed = (url: string, platform: string) => {
    let embed = '';
    if (platform === 'YouTube') {
      const vid = url.match(/(?:youtu\.be\/|youtube\.com\/(?:.*v=|.*\/|.*u\/\w\/|embed\/))([^#&?]*)/);
      if (vid && vid[1]) embed = `https://www.youtube.com/embed/${vid[1]}`;
    } else if (platform === 'Spotify') {
      const eid = url.match(/episode\/([a-zA-Z0-9]+)/);
      if (eid && eid[1]) embed = `https://open.spotify.com/embed/episode/${eid[1]}`;
    } else if (platform === 'RedCircle') {
      // RedCircle often uses a specific ID in their share links
      const rid = url.match(/episodes\/([a-zA-Z0-9-]+)/);
      if (rid && rid[1]) embed = `https://redcircle.com/episodes/${rid[1]}/embed`;
      else if (url.includes('embed')) embed = url; // Already an embed link
    }
    return embed;
  };

  useEffect(() => {
    const resolved = resolveEmbed(podcastForm.sourceUrl, podcastForm.platform);
    if (resolved) setPodcastForm(prev => ({ ...prev, embedUrl: resolved }));
  }, [podcastForm.sourceUrl, podcastForm.platform]);

  const generateSEOForPodcast = async () => {
    if (!podcastForm.sourceUrl && !podcastForm.title) {
      showToast("Provide a title or link to generate a neural SEO signal.", "error");
      return;
    }
    setIsGeneratingSEO(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create a high-impact, SEO-optimized title and a 3-sentence description for a theological podcast episode.
        Context: ${podcastForm.title} ${podcastForm.sourceUrl}.
        Style: Prophetic, unsealed, mysterious, high-tech theological.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: "OBJECT",
            properties: {
              title: { type: "STRING" },
              description: { type: "STRING" }
            },
            required: ["title", "description"]
          }
        }
      });
      const data = JSON.parse(response.text);
      setPodcastForm(prev => ({ ...prev, title: data.title, description: data.description }));
      showToast("SEO Signal Synchronized.", "success");
    } catch (e) {
      showToast("Neural link unstable.", "error");
    } finally {
      setIsGeneratingSEO(false);
    }
  };

  const handleAddPodcast = (e: React.FormEvent) => {
    e.preventDefault();
    if (!podcastForm.embedUrl) {
      showToast("Node Resolution failed. Invalid embed URL.", "error");
      return;
    }
    addPodcast({
      title: podcastForm.title,
      description: podcastForm.description,
      thumbnail: podcastForm.thumbnail,
      episodeNumber: podcastForm.episodeNumber,
      embedUrl: podcastForm.embedUrl,
      platform: podcastForm.platform
    });
    setPodcastForm({ 
      title: '', 
      description: '', 
      thumbnail: '', 
      episodeNumber: podcasts.length + 2, 
      sourceUrl: '', 
      embedUrl: '', 
      platform: 'YouTube' 
    });
    showToast("Neural Stream broadcast initialized.", "success");
  };

  const handleLogout = () => {
    logout();
    showToast("Neural Link Terminated.", "info");
    navigate("/");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: string) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (type === 'podcast') setPodcastForm(prev => ({ ...prev, thumbnail: base64String }));
        showToast("Visual asset buffered.", "info");
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 md:p-10 font-exo">
      <div className="max-w-7xl mx-auto">
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div className="flex items-center gap-6">
            <div>
              <h1 className="font-orbitron font-black text-4xl mb-2 tracking-tight text-white uppercase">Command Center</h1>
              <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                <p className="text-slate-500 font-bold text-[10px] uppercase tracking-widest">Protocol: <span className="text-slate-300">VEIL_ACTIVE</span></p>
              </div>
            </div>
            <button onClick={handleLogout} className="px-4 py-2 border border-red-500/30 text-red-500 rounded-xl font-orbitron font-bold text-[8px] uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all">De-sync Node</button>
