              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-5 py-2.5 rounded-xl text-[10px] font-orbitron font-bold uppercase tracking-widest transition-all ${
                  activeTab === tab ? 'gradient-bg text-white' : 'text-slate-500 hover:text-white'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>
        </header>

