      return;
    }
    setIsGeneratingBlogAI(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Act as a senior theologian and SEO specialist for Trick Theology. 
        Synthesize a 1-sentence mysterious and compelling abstract (excerpt) for this revelation:

        Title: ${blogForm.title}
        Category: ${blogForm.category}
        Content: ${blogForm.content.substring(0, 1500)}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              abstract: { type: Type.STRING }
            },
            required: ["abstract"]
          }
        }
      });
      const data = JSON.parse(response.text);
      setBlogForm(prev => ({ ...prev, excerpt: data.abstract }));
