// --- Rich Text Editor Component ---
interface RichTextEditorProps {
  content: string;
  onChange: (html: string) => void;
}

const RichTextEditor: React.FC<RichTextEditorProps> = ({ content, onChange }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const colorInputRef = useRef<HTMLInputElement>(null);

  const exec = (command: string, value?: string) => {
    document.execCommand(command, false, value);
    if (editorRef.current) {
      onChange(editorRef.current.innerHTML);
    }
  };

  const insertImage = () => {
    const url = prompt("Enter Image URL:");
    if (!url) return;
    const align = prompt("Align (left, right, center):", "left");

    let style = "max-width: 100%; height: auto; border-radius: 1rem; margin: 1rem;";
    if (align === "left") style += " float: left; margin-left: 0;";
    else if (align === "right") style += " float: right; margin-right: 0;";
    else style += " display: block; margin: 1rem auto; float: none;";

    const imgTag = `<img src="${url}" style="${style}" alt="Blog Image" />`;
    exec("insertHTML", imgTag);
  };

  return (
    <div className="flex flex-col border border-slate-800 rounded-3xl overflow-hidden bg-slate-950">
      {/* Toolbar */}
      <div className="flex flex-wrap gap-1 p-2 bg-slate-900/50 border-b border-slate-800 backdrop-blur-xl sticky top-0 z-10">
        <button type="button" onClick={() => exec('bold')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-xs font-bold" title="Bold">B</button>
        <button type="button" onClick={() => exec('italic')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-xs italic" title="Italic">I</button>
        <button type="button" onClick={() => exec('underline')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-xs underline" title="Underline">U</button>
        <button type="button" onClick={() => exec('strikeThrough')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-xs line-through" title="Strike">S</button>

        <div className="w-px h-4 bg-slate-800 self-center mx-1"></div>

        <button type="button" onClick={() => exec('formatBlock', 'H1')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black" title="H1">H1</button>
        <button type="button" onClick={() => exec('formatBlock', 'H2')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black" title="H2">H2</button>
        <button type="button" onClick={() => exec('formatBlock', 'H3')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black" title="H3">H3</button>
        <button type="button" onClick={() => exec('formatBlock', 'H4')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black" title="H4">H4</button>
        <button type="button" onClick={() => exec('formatBlock', 'H5')} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black" title="H5">H5</button>

        <div className="w-px h-4 bg-slate-800 self-center mx-1"></div>

        <button type="button" onClick={() => colorInputRef.current?.click()} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors flex items-center gap-1" title="Text Color">
          <div className="w-3 h-3 rounded-full bg-brand-start border border-white/20"></div>
          <input 
            type="color" 
            ref={colorInputRef} 
            className="hidden" 
            onChange={(e) => exec('foreColor', e.target.value)} 
          />
        </button>

        <button type="button" onClick={insertImage} className="p-2 hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black flex items-center gap-1" title="Insert Image">
          <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          IMG
        </button>

        <button type="button" onClick={() => exec('removeFormat')} className="p-2 hover:bg-red-500/20 rounded-lg transition-colors text-[10px] font-black text-red-400" title="Clear Formatting">CLR</button>
      </div>

      {/* Editable Area */}
      <div
        ref={editorRef}
        contentEditable
        onInput={(e) => onChange(e.currentTarget.innerHTML)}
        className="min-h-[300px] p-6 text-slate-300 outline-none focus:ring-1 focus:ring-brand-start/30 prose prose-invert prose-sm max-w-none prose-headings:font-orbitron prose-headings:uppercase"
        dangerouslySetInnerHTML={{ __html: content }}
        style={{ caretColor: '#c900ff' }}
      />
    </div>
  );
};

