// --- Rich Text Editor Component ---
interface RichTextEditorProps {
  content: string;
  onChange: (html: string) => void;
}

const RichTextEditor: React.FC<RichTextEditorProps> = ({ content, onChange }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const colorInputRef = useRef<HTMLInputElement>(null);

  const exec = (command: string, value?: string) => {
    document.execCommand(command, false, value);
    if (editorRef.current) {
      onChange(editorRef.current.innerHTML);
    }
  };

  const insertImage = () => {
    const url = prompt("Enter Image URL:");
    if (!url) return;
    const align = prompt("Align (left, right, center):", "left");

    let style = "max-width: 40%; height: auto; border-radius: 1rem; margin: 1rem;";
    if (align === "left") style += " float: left; margin-left: 0;";
    else if (align === "right") style += " float: right; margin-right: 0;";
    else style = "max-width: 100%; display: block; margin: 1rem auto; float: none; border-radius: 1rem;";

    const imgTag = `<img src="${url}" style="${style}" alt="Blog Image" />`;
    exec("insertHTML", imgTag);
  };

  return (
    <div className="flex flex-col border border-slate-800 rounded-3xl overflow-hidden bg-slate-950">
      {/* Toolbar */}
      <div className="flex flex-wrap gap-1 p-3 bg-slate-900/50 border-b border-slate-800 backdrop-blur-xl sticky top-0 z-10">
        <button type="button" onClick={() => exec('bold')} className="w-8 h-8 flex items-center justify-center hover:bg-brand-start/20 rounded-lg transition-colors text-xs font-bold border border-slate-800" title="Bold">B</button>
        <button type="button" onClick={() => exec('italic')} className="w-8 h-8 flex items-center justify-center hover:bg-brand-start/20 rounded-lg transition-colors text-xs italic border border-slate-800" title="Italic">I</button>
        <button type="button" onClick={() => exec('underline')} className="w-8 h-8 flex items-center justify-center hover:bg-brand-start/20 rounded-lg transition-colors text-xs underline border border-slate-800" title="Underline">U</button>
        <button type="button" onClick={() => exec('strikeThrough')} className="w-8 h-8 flex items-center justify-center hover:bg-brand-start/20 rounded-lg transition-colors text-xs line-through border border-slate-800" title="Strike">S</button>
        <div className="w-px h-6 bg-slate-800 self-center mx-2"></div>
        <button type="button" onClick={() => exec('formatBlock', 'H1')} className="px-2 h-8 flex items-center justify-center hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black border border-slate-800" title="H1">H1</button>
        <button type="button" onClick={() => exec('formatBlock', 'H2')} className="px-2 h-8 flex items-center justify-center hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black border border-slate-800" title="H2">H2</button>
        <button type="button" onClick={() => exec('formatBlock', 'H3')} className="px-2 h-8 flex items-center justify-center hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black border border-slate-800" title="H3">H3</button>
        <button type="button" onClick={() => exec('formatBlock', 'H4')} className="px-2 h-8 flex items-center justify-center hover:bg-brand-start/20 rounded-lg transition-colors text-[10px] font-black border border-slate-800" title="H4">H4</button>
